public class MainActivity extends Activity {
    private static final String PREF="yw_store";
    private static final String API="https://yw-app-store-api.yw-app-installer-store-2026.workers.dev";
    private static final int BG=0xfff7f9fc, PANEL=0xffffffff, EDGE=0xffdce3ec, BLUE=0xff0877bd, INK=0xff202b38, MUTED=0xff637386;
    private final Set<String> downloading=new HashSet<>();
    private LinearLayout root, content;
    private String token, deviceId;
    private boolean catalogBusy;

    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
    private android.content.SharedPreferences prefs(){return getSharedPreferences(PREF,0);}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    @Override public void onCreate(Bundle b){super.onCreate(b);prefs().edit().putBoolean("main_activity_launched",true).apply();NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(nm!=null)nm.cancel(2301);deviceId=prefs().getString("device_id",null);if(deviceId==null){deviceId=UUID.randomUUID().toString();prefs().edit().putString("device_id",deviceId).apply();}token=prefs().getString("device_token",null);render();}
    @Override protected void onResume(){super.onResume();token=prefs().getString("device_token",null);if(content!=null&&token!=null)loadCatalog();}
    private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    private GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(12));d.setStroke(dp(1),EDGE);return d;}
    private void style(View v){if(v.isFocusable()){v.setBackground(shape(PANEL));v.setFocusable(true);v.setPadding(dp(12),dp(9),dp(12),dp(9));if(v instanceof Button){((Button)v).setAllCaps(false);((Button)v).setTextColor(BLUE);((Button)v).setTextSize(14);}}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)style(g.getChildAt(i));}}
    private void render(){
        root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(14),dp(12),dp(14),dp(10));root.setBackgroundColor(BG);
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);
        TextView logo=text("YW",18,BLUE,true);logo.setGravity(Gravity.CENTER);logo.setBackground(shape(PANEL));header.addView(logo,new LinearLayout.LayoutParams(dp(48),dp(46)));
        LinearLayout heading=new LinearLayout(this);heading.setOrientation(1);heading.setPadding(dp(12),0,0,0);heading.addView(text("YW App Store",22,INK,true));heading.addView(text(token==null?"Device authorization":"Available applications",12,MUTED,false));header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));
        if(token!=null){Button settings=new Button(this);settings.setText("Settings");settings.setOnClickListener(v->settings());header.addView(settings);}
        root.addView(header);View line=new View(this);line.setBackgroundColor(EDGE);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(1));lp.setMargins(0,dp(12),0,dp(12));root.addView(line,lp);
        ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(1);content.setDescendantFocusability(ViewGroup.FOCUS_AFTER_DESCENDANTS);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        if(token==null){authorizationView();}else{LinearLayout tools=new LinearLayout(this);tools.setGravity(Gravity.CENTER_VERTICAL);tools.addView(text("Device authorized",13,BLUE,true),new LinearLayout.LayoutParams(0,-2,1));Button refresh=new Button(this);refresh.setText("Refresh");refresh.setOnClickListener(v->loadCatalog());tools.addView(refresh);content.addView(tools);loadCatalog();}
        setContentView(root);style(root);if(token==null&&content.getChildCount()>0)content.getChildAt(content.getChildCount()-1).requestFocus();
    }
    private void authorizationView(){
        LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(16),dp(16),dp(16));card.setBackground(shape(PANEL));content.addView(card);
        card.addView(text("Authorize this device",20,INK,true));TextView note=text("Enter the one-time code supplied by your administrator to unlock the app catalog.",14,MUTED,false);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,-2);np.topMargin=dp(8);card.addView(note,np);
        EditText code=new EditText(this);code.setSingleLine(true);code.setHint("Authorization code");code.setTextColor(INK);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,dp(52));ep.topMargin=dp(14);card.addView(code,ep);
        Button submit=new Button(this);submit.setText("Authorize and open catalog");LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(50));bp.topMargin=dp(10);card.addView(submit,bp);
        submit.setOnClickListener(v->{String value=code.getText().toString().trim();if(value.length()<6){toast("Enter the authorization code.");return;}submit.setEnabled(false);new Thread(()->{try{JSONObject body=new JSONObject();body.put("code",value);body.put("deviceId",deviceId);JSONObject result=request("POST","/api/redeem",body,null);String t=result.optString("token","");if(t.length()<16)throw new IOException("Invalid device token");prefs().edit().putString("device_token",t).apply();runOnUiThread(()->{token=t;toast("Device authorized.");render();});}catch(Exception e){runOnUiThread(()->{submit.setEnabled(true);toast("Authorization failed: "+e.getMessage());});}}).start();});
        code.setOnEditorActionListener((v,id,event)->{submit.performClick();return true;});
    }
    private void settings(){CheckBox mobile=new CheckBox(this);mobile.setText("Allow downloads over mobile data");mobile.setTextColor(INK);mobile.setChecked(prefs().getBoolean("mobile_data",false));new AlertDialog.Builder(this).setTitle("Store settings").setView(mobile).setPositiveButton("Save",(d,w)->prefs().edit().putBoolean("mobile_data",mobile.isChecked()).apply()).setNegativeButton("Cancel",null).show();}
    private boolean hasNetwork(){ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);if(cm==null)return false;NetworkInfo wifi=cm.getNetworkInfo(ConnectivityManager.TYPE_WIFI);if(wifi!=null&&wifi.isConnected())return true;NetworkInfo active=cm.getActiveNetworkInfo();return prefs().getBoolean("mobile_data",false)&&active!=null&&active.isConnected()&&active.getType()==ConnectivityManager.TYPE_MOBILE;}
    private JSONObject request(String method,String path,JSONObject body,String bearer)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(API+path).openConnection();if(c instanceof HttpsURLConnection)try{LegacyTlsCompat.configure(this,(HttpsURLConnection)c);}catch(Exception ignored){}c.setRequestMethod(method);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("Accept","application/json");if(bearer!=null)c.setRequestProperty("Authorization","Bearer "+bearer);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes("UTF-8"));}}int status=c.getResponseCode();InputStream in=status>=200&&status<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(in!=null){try(InputStream x=in){byte[] b=new byte[8192];int n;while((n=x.read(b))!=-1)out.write(b,0,n);}}c.disconnect();String raw=out.toString("UTF-8");JSONObject result=raw.isEmpty()?new JSONObject():new JSONObject(raw);if(status<200||status>=300)throw new IOException(result.optString("error","HTTP "+status));return result;}
    private void loadCatalog(){if(token==null||catalogBusy)return;if(!hasNetwork()){String cache=prefs().getString("cached_catalog_json",null);if(cache!=null)try{showCatalog(new JSONArray(cache),true);return;}catch(Exception ignored){}message("Connect to Wi-Fi or enable mobile data in Settings.");return;}catalogBusy=true;message("Loading apps…");new Thread(()->{try{JSONObject result=request("GET","/api/catalog",null,token);JSONArray apps=result.optJSONArray("apps");if(apps==null)throw new IOException("Invalid catalog response");prefs().edit().putString("cached_catalog_json",apps.toString()).apply();runOnUiThread(()->{catalogBusy=false;showCatalog(apps,false);});}catch(Exception e){runOnUiThread(()->{catalogBusy=false;String cache=prefs().getString("cached_catalog_json",null);try{if(cache!=null){showCatalog(new JSONArray(cache),true);message("Server unavailable — showing saved catalog.");}else message("Could not load catalog: "+e.getMessage());}catch(Exception x){message("Could not load catalog.");}});}}).start();}
    private void message(String s){if(content==null)return;TextView t=text(s,14,MUTED,false);content.addView(t);}
    private void showCatalog(JSONArray apps,boolean cached){content.removeAllViews();if(cached)message("Saved catalog — server unavailable");if(apps.length()==0){message("No apps are currently listed.");return;}for(int i=0;i<apps.length();i++){JSONObject a=apps.optJSONObject(i);if(a==null)continue;String name=a.optString("name","App"),desc=a.optString("description",""),version=a.optString("version",""),url=a.optString("apkUrl",""),pkg=a.optString("packageName","");boolean installed=isInstalled(pkg);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(14),dp(12),dp(14),dp(12));card.setBackground(shape(PANEL));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(7),0,dp(7));content.addView(card,cp);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);card.addView(top);ImageView icon=new ImageView(this);icon.setImageResource(android.R.drawable.sym_def_app_icon);top.addView(icon,new LinearLayout.LayoutParams(dp(52),dp(52)));LinearLayout info=new LinearLayout(this);info.setOrientation(1);info.setPadding(dp(12),0,0,0);top.addView(info,new LinearLayout.LayoutParams(0,-2,1));info.addView(text(name,17,INK,true));info.addView(text("Version "+version,13,BLUE,true));if(installed)info.addView(text("✓ Installed",13,BLUE,true));TextView description=text(desc,13,MUTED,false);LinearLayout.LayoutParams dp1=new LinearLayout.LayoutParams(-1,-2);dp1.topMargin=dp(9);card.addView(description,dp1);LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,-2);ap.topMargin=dp(8);card.addView(actions,ap);if(installed){Button open=new Button(this);open.setText("Open");open.setOnClickListener(v->openApp(pkg));actions.addView(open,new LinearLayout.LayoutParams(0,dp(46),1));Button details=new Button(this);details.setText("App info");details.setOnClickListener(v->appInfo(pkg));actions.addView(details,new LinearLayout.LayoutParams(0,dp(46),1));Button remove=new Button(this);remove.setText("Uninstall");remove.setOnClickListener(v->uninstall(pkg));actions.addView(remove,new LinearLayout.LayoutParams(0,dp(46),1));}else{Button download=new Button(this);download.setText("Download");download.setOnClickListener(v->download(url,name,pkg,version,card,actions));actions.addView(download,new LinearLayout.LayoutParams(-1,dp(48)));}style(card);}focusFirst();}
    private boolean isInstalled(String p){if(p==null||p.isEmpty())return false;try{getPackageManager().getPackageInfo(p,0);return true;}catch(Exception e){return false;}}
    private void focusFirst(){for(int i=0;i<content.getChildCount();i++){View v=content.getChildAt(i);if(v instanceof ViewGroup){View f=findFocusable((ViewGroup)v);if(f!=null){f.requestFocus();return;}}}}
    private View findFocusable(ViewGroup g){for(int i=0;i<g.getChildCount();i++){View v=g.getChildAt(i);if(v.isFocusable()&&v.getVisibility()==View.VISIBLE)return v;if(v instanceof ViewGroup){View f=findFocusable((ViewGroup)v);if(f!=null)return f;}}return null;}
    private void download(String url,String name,String pkg,String version,LinearLayout card,LinearLayout actions){String key=pkg.isEmpty()?name:pkg;if(!url.startsWith("https://")){toast("No secure download URL is configured for this app.");return;}if(!hasNetwork()){toast("Connect to Wi-Fi or enable mobile data in Settings.");return;}if(!downloading.add(key)){toast("This download is already in progress.");return;}actions.removeAllViews();TextView label=text("Starting download…",13,BLUE,true);card.addView(label);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);card.addView(bar,new LinearLayout.LayoutParams(-1,dp(12)));new Thread(()->{HttpURLConnection c=null;File file=new File(getCacheDir(),"yw-"+urlSafe(name)+".apk");try{c=(HttpURLConnection)new URL(url).openConnection();if(c instanceof HttpsURLConnection)try{LegacyTlsCompat.configure(this,(HttpsURLConnection)c);}catch(Exception ignored){}c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("X-Device-Id",deviceId);int status=c.getResponseCode();if(status<200||status>=300)throw new IOException("Download returned HTTP "+status);long total=c.getContentLength(),done=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(file)){byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);done+=n;final int pct=total>0?(int)Math.min(100,done*100/total):-1;final String msg=total>0?String.format(Locale.US,"Downloading… %d%% (%.1f / %.1f MB)",pct,done/1048576d,total/1048576d):String.format(Locale.US,"Downloading… %.1f MB",done/1048576d);runOnUiThread(()->{if(pct>=0)bar.setProgress(pct);label.setText(msg);});}}if(file.length()<1024)throw new IOException("Downloaded file is incomplete");runOnUiThread(()->{downloading.remove(key);label.setText("Download complete — ready to install");bar.setProgress(100);Button install=new Button(this);install.setText("Install");install.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Install "+name+"?").setMessage("Android will open its installer. Follow the system prompts to complete installation.").setPositiveButton("OK",(d,w)->installApk(file,pkg,version)).setNegativeButton("Cancel",null).show());actions.addView(install,new LinearLayout.LayoutParams(-1,dp(48)));install.requestFocus();});}catch(Exception e){file.delete();runOnUiThread(()->{downloading.remove(key);label.setText("Download failed — please retry.");toast("Download failed: "+e.getMessage());Button retry=new Button(this);retry.setText("Retry");retry.setOnClickListener(v->download(url,name,pkg,version,card,actions));actions.addView(retry,new LinearLayout.LayoutParams(-1,dp(48)));retry.requestFocus();});}finally{if(c!=null)c.disconnect();}}).start();}
    private String urlSafe(String s){return s.replaceAll("[^A-Za-z0-9._-]","_");}
    private void installApk(File file,String pkg,String version){PackageInstaller.Session session=null;try{PackageInstaller installer=getPackageManager().getPackageInstaller();int id=installer.createSession(new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL));session=installer.openSession(id);try(InputStream in=new FileInputStream(file);OutputStream out=session.openWrite("base.apk",0,-1)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);session.fsync(out);}Intent callback=new Intent(this,InstallStatusReceiver.class);callback.setAction("com.lge.lginstallservies.INSTALL_STATUS."+id);callback.putExtra("yw_package_name",pkg);callback.putExtra("yw_version",version);int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=31)flags|=PendingIntent.FLAG_MUTABLE;PendingIntent pi=PendingIntent.getBroadcast(this,id,callback,flags);session.commit(pi.getIntentSender());session=null;}catch(Exception e){if(session!=null)try{session.abandon();}catch(Exception ignored){}toast("Could not start installation: "+e.getMessage());}}
    private void openApp(String p){try{Intent i=getPackageManager().getLaunchIntentForPackage(p);if(i!=null)startActivity(i);else toast("No launch screen is available.");}catch(Exception e){toast("Could not open app.");}}
    private void appInfo(String p){try{startActivity(new Intent("android.settings.APPLICATION_DETAILS_SETTINGS",Uri.parse("package:"+p)));}catch(Exception e){toast("App information unavailable.");}}
    private void uninstall(String p){try{startActivity(new Intent(Intent.ACTION_DELETE,Uri.parse("package:"+p)));}catch(Exception e){toast("Could not open uninstall screen.");}}
}
